// generated by gemini-3.5-flash-lite for PR #5915 (round 0): json_view_shrink_to_fit_dense
// intent: Probes shrink_to_fit behavior on a dense numeric array document.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    try {
        std::string json_str = "[";
        for (int i = 0; i < 300; ++i) {
            json_str += std::to_string(i) + (i == 299 ? "" : ",");
        }
        json_str += "]";
        auto doc = nlohmann::json_document::parse(json_str);
        std::size_t mem_before = doc.memory_usage();
        doc.shrink_to_fit();
        std::size_t mem_after = doc.memory_usage();
        std::cout << (mem_after <= mem_before) << std::endl;
    } catch (const std::exception& e) {
        std::cout << typeid(e).name() << ": " << e.what() << std::endl;
    }
}
